// ensureReplayableBody derives req.GetBody for seekable readers.
// http.NewRequestWithContext only sets GetBody for *bytes.Buffer,
// *bytes.Reader and *strings.Reader; without it the retry transport cannot
// resend the body, so a 429/5xx on any other reader type (an *os.File, a
// caller-built multipart body, ...) failed immediately instead of retrying.
// Non-seekable readers are left as-is: they stream once and are never
// retried.
func ensureReplayableBody(req *http.Request, body io.Reader) {
	if req.GetBody != nil || body == nil {
		return
	}
	seeker, ok := body.(io.Seeker)
	if !ok {
		return
	}
	start, err := seeker.Seek(0, io.SeekCurrent)
	if err != nil {
		return
	}
	req.GetBody = func() (io.ReadCloser, error) {
		if _, err := seeker.Seek(start, io.SeekStart); err != nil {
			return nil, err
		}
		return io.NopCloser(body), nil
	}
}

