func TestFilesService_Upload_RetriesOn429(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var attempts int
	policy := pipedrive.RetryPolicy{MaxAttempts: 2}
	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		attempts++
		attempt := attempts
		mu.Unlock()

		// Every attempt, including the rate-limited one, must receive the
		// complete multipart body.
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Errorf("attempt %d: parse multipart form: %v", attempt, err)
		}
		files := r.MultipartForm.File["file"]
		if len(files) != 1 || files[0].Filename != "doc.txt" {
			t.Errorf("attempt %d: unexpected file parts: %#v", attempt, files)
		}

		if attempt == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":5,"file_name":"doc.txt"}}`))
	})

	file, err := client.Files.Upload(context.Background(), "doc.txt", strings.NewReader("payload"))
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 5 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
}

